def build_middle_east():
    count = 0
    for code, (name, trans) in MIDDLE_EAST_LANGS.items():
        build_po(code, name, trans)
        count += 1
    return count

if __name__ == "__main__":
    print(f"Built {build_middle_east()} Middle Eastern languages.")
